mapper.update:
UPDATE CHALLENGE
SET
    DELETE_YN = 1,
    UPDATED_BY = #{adminId},
    UPDATED_AT = #{updatedAt}

WHERE CODE = #{code}
  AND DELETE_YN = 0

  AND NOT EXISTS (
      SELECT 1
      FROM CHALLENGE_ENTRY ce
      WHERE ce.CHAL_CODE = #{code}
  )

  AND NOT EXISTS (
      SELECT 1
      FROM FEED f
      WHERE f.CHAL_CODE = #{code}
  )

UPDATE CHALLENGE
SET
    PROGRESS_STATUS = 'ENDED',
    END_DATE = #{endedAt},
    UPDATED_BY = #{adminId},
    UPDATED_AT = #{endedAt}

WHERE CODE = #{code}
  AND DELETE_YN = 0
  AND PROGRESS_STATUS IN ('WAITING', 'IN_PROGRESS')
  AND START_DATE <= #{endedAt}
  AND END_DATE > #{endedAt}
